window.KD_CONTENT = {"roles": {"R01": {"title": "Das Kind des Professors", "pages": ["", "", "", ""], "culprit": false}, "R02": {"title": "Die frühere Forschungspartnerschaft", "pages": ["", "", "", ""], "culprit": false}, "R03": {"title": "Die Kanzlei der Stiftung", "pages": ["", "", "", ""], "culprit": false}, "R04": {"title": "Die Presse", "pages": ["", "", "", ""], "culprit": false}, "R05": {"title": "Die Veranstaltungsleitung", "pages": ["", "", "", ""], "culprit": false}, "R06": {"title": "Die Küchenleitung", "pages": ["", "", "", ""], "culprit": false}, "R07": {"title": "Die ärztliche Vertrauensperson", "pages": ["", "", "", ""], "culprit": false}, "R08": {"title": "Die Archivleitung — TÄTERROLLE", "pages": ["", "", "", ""], "culprit": true}, "R09": {"title": "Die technische Leitung", "pages": ["", "", "", ""], "culprit": false}, "R10": {"title": "Die private Sammlung", "pages": ["", "", "", ""], "culprit": false}}, "cards": {"B1": {"round": 1, "icon": "✦", "title": "Tatortbericht", "html": "", "foot": "Freigabe: Runde 1"}, "B2": {"round": 1, "icon": "☏", "title": "Erste ärztliche Einschätzung", "html": "eRldVAxQIhdCU35UXFJQTjtYRUBfTVVCSEosV19HFVBsWRxNz7GnZF5JNgcfFwcDQQgDDDYKCw0LTloHUkEcCwgAEVg9EEVAX01TR0hKJ1dNSCAHCEUJGkNLXFxfSCFUNhEGGwAVVBMqB0MADAASAAJfDVxQRBFIOhoAH04EAhoDADcMDURFBQcLGBpKVFcQdkg0EQsBGhYPFlpFFh0CGg4LRicABllEV1cfz9PoWV0eSQ==", "foot": "Freigabe: Runde 1"}, "B3": {"round": 1, "icon": "☰", "title": "Grundriss und Schließanlage", "html": "", "foot": "Freigabe: Runde 1"}, "B4": {"round": 1, "icon": "✎", "title": "Ablaufplan des Abends", "html": "", "foot": "Freigabe: Runde 1"}, "B5": {"round": 2, "icon": "✎", "title": "Sanders Tischkalender", "html": "", "foot": "Freigabe: Runde 2"}, "B6": {"round": 2, "icon": "☰", "title": "Archivliste Himmelsatlas (Auszug)", "html": "", "foot": "Freigabe: Runde 2"}, "B7": {"round": 2, "icon": "✦", "title": "Fund unter dem Kartentisch", "html": "eRldLQwARg4AFkRfXEMRETFKIwcAHAwbHxcqDwwGWUEEW0BTSFhXV1ReMBwEHhoSFV5UCCwdQyMJCwQADhJDVRlFX1k2BkUWCwVBJh0WJgETBAQaEgBMEUhXXENFRDQAS1IqHgRSNgQxHQYaDAtGDB8HDVdYQ0UNJRsJHkBXJBsaRQAEEw6myggCCQENWEpEEUM6Fw0GTg0UUhIMKw0GBktSSRVS", "foot": "Freigabe: Runde 2"}, "B8": {"round": 2, "icon": "☏", "title": "Nachtrag von Dr. Seebach", "html": "", "foot": "Freigabe: Runde 2 · Bedingung: R07 nicht besetzt"}, "B9": {"round": 3, "icon": "☰", "title": "Zutrittsprotokoll 20:30–21:40", "html": "", "foot": "Freigabe: Runde 3"}, "B10": {"round": 3, "icon": "☰", "title": "Technikprotokoll der Hauptverteilung", "html": "", "foot": "Freigabe: Runde 3"}, "B11": {"round": 3, "icon": "☏", "title": "Aussage aus der Küche", "html": "", "foot": "Freigabe: Runde 3 · immer"}, "B12": {"round": 3, "icon": "◉", "title": "Aufnahme des Funkmikrofons (Abschrift)", "html": "", "foot": "Freigabe: Runde 3 · Bedingung: R04 nicht besetzt oder Aufnahme noch nicht vorgelegt"}, "B13": {"round": 4, "icon": "✦", "title": "Die Transportkiste", "html": "", "foot": "Freigabe: Finale"}, "B14": {"round": 4, "icon": "✎", "title": "Sanders Redemanuskript", "html": "", "foot": "Freigabe: Finale"}}, "hostA": "<h1>Teil A · Vorbereitung und Ablauf</h1>\n<h2>A1 · Deine Aufgabe</h2>\n<p>Du bist Erzählstimme, Zeitwächter und Beweisausgabe. Du liest zu Beginn jeder Phase einen kurzen Text vor, gibst die Beweise frei und achtest darauf, dass der Abend im Fluss bleibt. Den Fall löst du nicht – das machen die Gäste. <b>Du darfst mitspielen.</b> Deine Rolle öffnest du mit deinem eigenen Code wie alle anderen. Wer welche Rolle hat, siehst du nicht, auch nicht, ob du selbst die Täterrolle hast, bevor du dein Blatt öffnest.</p>\n<h2>A2 · Vorbereitung (eine Woche bis zwei Tage vorher)</h2>\n<ul><li><span class=\"box\"></span><b>Gäste einladen:</b> 4 bis 10 Personen, Dauer etwa 2½ Stunden plus Essen.</li><li><span class=\"box\"></span><b>Namen und Rollenvarianten eintragen</b> (weiblich oder männlich dargestellt – jede Person wählt frei).</li><li><span class=\"box\"></span><b>Codes verteilen</b>, jeder Person ihren eigenen. Einen Code nur der jeweiligen Person geben, nie offen in eine Gruppe schreiben.</li><li><span class=\"box\"></span><b>Anleitung mitschicken</b> (<code>ANLEITUNG</code>), damit alle die fünf Regeln kennen.</li><li><span class=\"box\"></span><b>Hinweis an alle:</b> Rollenblatt zwei, drei Tage vorher lesen. Requisiten mit „Pflicht“ mitbringen.</li><li><span class=\"box\"></span><b>Bei der Druckversion:</b> Beweiskarten drucken und nach Runden sortieren (Farbe der Runde). B13 und B14 in einen Umschlag „Erst nach der Anklage öffnen“. Dieses Heft drucken, Teil B in einen eigenen Umschlag.</li><li><span class=\"box\"></span><b>Am Abend bereitlegen:</b> Zettel und Stifte für alle (Zeitleiste!), Anklagezettel (A6), eine Uhr gut sichtbar, gedämpftes Licht und ein paar Kerzen für Phase 2.</li></ul>\n<h2>A3 · Besetzung und Zusatzkarten</h2>\n<p>Die Rollen werden in dieser Reihenfolge besetzt. Alle nicht besetzten Rollen sind <b>Nebenfiguren</b>: Sie sind „im Haus“, aber niemand spielt sie.</p>\n<table><thead><tr><th>Personen</th><th>besetzte Rollen</th></tr></thead><tbody><tr><td>4</td><td>R02 Marwitz · R08 Rademacher · R09 Faber · R10 Falk</td></tr><tr><td>5</td><td>+ R01 Leonie/Leon Sander</td></tr><tr><td>6</td><td>+ R03 Ritter</td></tr><tr><td>7</td><td>+ R06 Yilmaz</td></tr><tr><td>8</td><td>+ R04 Lindner</td></tr><tr><td>9</td><td>+ R05 Hollerbach</td></tr><tr><td>10</td><td>+ R07 Seebach</td></tr></tbody></table>\n<p><b>Zusatzkarten, je nach Besetzung:</b></p>\n<table><thead><tr><th>Karte</th><th>wann zusätzlich freigeben</th></tr></thead><tbody><tr><td>B8 · Nachtrag Dr. Seebach</td><td>in Runde 2, <b>wenn R07 nicht besetzt ist</b></td></tr><tr><td>B12 · Aufnahme des Funkmikrofons</td><td>in Runde 3, <b>wenn R04 nicht besetzt ist</b> oder Lindner die Aufnahme bis dahin nicht vorgelegt hat</td></tr></tbody></table>\n<p>Alle anderen Karten kommen in jeder Besetzung.</p>\n<h2>A4 · Zeitplan (Vorschlag)</h2>\n<table><thead><tr><th>Uhrzeit am Abend</th><th>Phase</th><th>Beweise</th></tr></thead><tbody><tr><td>0:00</td><td>Ankommen, Getränk, Regeln vorlesen (A5)</td><td>–</td></tr><tr><td>0:10</td><td><b>Phase 1 · Der Empfang</b> (Vorspeise)</td><td>–</td></tr><tr><td>0:30</td><td><b>Phase 2 · Der Mord</b> (Hauptgang)</td><td>B1–B4</td></tr><tr><td>0:50</td><td><b>Phase 3 · Geheimnisse und Intrigen</b></td><td>B5–B7 (+ B8)</td></tr><tr><td>1:20</td><td><b>Phase 4 · Die letzte Ermittlung</b> (Dessert)</td><td>B9–B11 (+ B12)</td></tr><tr><td>1:45</td><td><b>Finale · Anklage und Auflösung</b></td><td>B13, B14</td></tr><tr><td>ca. 2:15</td><td>Ende, Nachgespräch</td><td>–</td></tr></tbody></table>\n<p>Lass dir Zeit, wenn das Gespräch gut läuft. Kürze, wenn es stockt (A7).</p>\n<h2>A5 · Vor dem Start vorlesen</h2>\n<blockquote><p>„Bevor wir beginnen, die Regeln. Erstens: Ihr dürft eure Geheimnisse für euch behalten, ausweichen und schweigen. Zweitens: Wer unschuldig ist, sagt über den eigenen Aufenthaltsort und die eigenen Handlungen zur Tatzeit die Wahrheit. Nur eine Person am Tisch darf darüber lügen – und sie weiß, dass sie gemeint ist. Drittens: Was auf einer Beweiskarte steht, ist wahr. Viertens: Trumpfkarten spielt ihr, wann ihr wollt. Fünftens: Die vierte Seite eures Rollenblatts zeigt ihr niemandem. Und jetzt: Willkommen in Eichenfels.“</p></blockquote>\n<hr>\n<h2>Phase 1 · Der Empfang (ca. 20 Min.)</h2>\n<blockquote><p><b>Vorlesen:</b> „Willkommen in der Sternwarte Eichenfels. Heute vor 125 Jahren wurde hier zum ersten Mal die Kuppel geöffnet. Draußen wird der Wind stärker, drinnen glänzt das Silber. Professor Theodor Sander hat Sie eingeladen – zehn Menschen, die mit diesem Haus verbunden sind, manche enger, als ihnen lieb ist. Bitte stellen Sie sich einander vor: Wer sind Sie, und was verbindet Sie mit dem Professor?“</p></blockquote>\n<p><b>Deine Aufgabe:</b> Jede Person stellt sich mit Seite 1 ihres Rollenblatts vor (Name, Beruf, Verbindung zu Sander). Danach stellst du die <b>Nebenfiguren</b> mit je einem Satz vor:</p>\n<table><thead><tr><th>Nebenfigur</th><th>Satz zum Vorlesen</th></tr></thead><tbody><tr><td>R01</td><td>„{R01: Leonie / Leon} Sander, das einzige Kind des Professors, Unternehmensberatung in Leipzig. Die beiden sehen sich selten.“</td></tr><tr><td>R03</td><td>„{R03: Johanna / Johannes} Ritter, Kanzlei der Stiftung, korrekt und verschwiegen, mit einer Aktentasche, die {R03: sie / er} nie abstellt.“</td></tr><tr><td>R04</td><td>„{R04: Clara / Carl} Lindner, Presse, schreibt eine Reportage zum Jubiläum.“</td></tr><tr><td>R05</td><td>„{R05: Tessa / Tom} Hollerbach, die Eventagentur, überall und nirgends.“</td></tr><tr><td>R06</td><td>„{R06: Mina / Emre} Yilmaz aus dem Landgasthof ‚Zum Kauz‘, heute in der Küche.“</td></tr><tr><td>R07</td><td>„Dr. {R07: Nina / Nils} Seebach, seit zwanzig Jahren Sanders {R07: Ärztin / Arzt} und {R07: Schachpartnerin / Schachpartner}.“</td></tr></tbody></table>\n<p><i>(Die Rollen R02, R08, R09 und R10 sind immer besetzt.)</i></p>\n<blockquote><p><b>Vorlesen (Sanders Ansprache, 20:40 Uhr):</b> „Liebe Gäste. Es gibt Wahrheiten, die Jahrzehnte überdauern. Es gibt Menschen, die ihren Ruhm auf der Arbeit anderer aufgebaut haben. Und es gibt Geheimnisse, die heute Nacht nicht länger verborgen bleiben. Um 22 Uhr werde ich Ihnen die Wahrheit erzählen – über diese Sternwarte, über den Himmelsatlas und über eine Person, die sich seit Jahren in Sicherheit wiegt. Bis dahin: Genießen Sie das Essen.“</p></blockquote>\n<p><b>Tipp:</b> Lass nach der Ansprache einen Moment Stille. Wer reagiert wie?</p>\n<hr>\n<h2>Phase 2 · Der Mord (ca. 20 Min.)</h2>\n<p><i>Wenn möglich: Licht dimmen, Kerzen an.</i></p>\n<blockquote><p><b>Vorlesen:</b> „Um 21:08 erlischt das Licht. Notlampen flackern, irgendwo schlägt eine Tür. Um 21:20 ist der Strom zurück. Das Dessert wird aufgetragen – aber der Platz des Professors bleibt leer. Um 21:35 hören Sie einen Schrei aus dem Westflügel. Professor Sander liegt tot im Kartenraum. Draußen tobt der Sturm, ein Baum blockiert die Zufahrt, das Netz ist schwach. Die Polizei kommt frühestens im Morgengrauen. Bis dahin sind Sie unter sich – und eine Person in diesem Raum hat es getan.“</p></blockquote>\n<p><b>Freigeben:</b> B1 Tatortbericht · B2 Ärztliche Einschätzung · B3 Grundriss und Schließanlage · B4 Ablaufplan</p>\n<p><b>Runde der Alibis:</b> Jede Person sagt der Reihe nach, wo sie zwischen 21:00 und 21:35 Uhr war. Erinnere an Regel 2. Für Nebenfiguren sagst du: „Das weiß im Moment niemand genau.“</p>\n<hr>\n<h2>Phase 3 · Geheimnisse und Intrigen (ca. 30 Min.)</h2>\n<blockquote><p><b>Vorlesen:</b> „Es ist gegen halb elf. Im Kartenraum finden sich Spuren, die nicht zu einem Unfall passen. Im Papierkorb des Archivs liegen Papierfetzen. Und unter dem Kartentisch klebt etwas, das dort nicht hingehört.“</p></blockquote>\n<p><b>Freigeben:</b> B5 Kalender · B6 Archivliste · B7 Funkmikrofon · <b>B8</b>, wenn R07 nicht besetzt ist</p>\n<p><b>Freies Gespräch:</b> Die Gäste befragen einander, gehen zu zweit beiseite, schließen Bündnisse, spielen Trumpfkarten.</p>\n<hr>\n<h2>Phase 4 · Die letzte Ermittlung (ca. 25 Min.)</h2>\n<blockquote><p><b>Vorlesen:</b> „Gegen halb zwölf gelingt es der Haustechnik, den Server im Keller auszulesen. Das Zutrittsprotokoll des Abends liegt auf dem Tisch. Und in der Küche erzählt die Aushilfe Jo, was ihr seltsam vorkam.“</p></blockquote>\n<p><b>Freigeben:</b> B9 Zutrittsprotokoll · B10 Technikprotokoll · B11 Aussage aus der Küche · <b>B12</b>, wenn R04 nicht besetzt ist oder die Aufnahme noch nicht auf dem Tisch liegt</p>\n<p><b>Tipp:</b> Schlag vor, gemeinsam eine Zeitleiste von 21:00 bis 21:35 aufzuschreiben, zum Beispiel auf einer Serviette in der Tischmitte.</p>\n<hr>\n<h2>Finale · Anklage und Auflösung (15–30 Min.)</h2>\n<blockquote><p><b>Vorlesen:</b> „Kurz nach Mitternacht meldet sich die Polizei über Funk: Im Morgengrauen ist die Zufahrt frei. Bevor sie kommt, sagt jede und jeder von Ihnen, was er glaubt: Wer hat Theodor Sander getötet? Warum? Und welcher Beweis überführt die Person?“</p></blockquote>\n<ol><li>Alle füllen verdeckt einen <b>Anklagezettel</b> aus (Vorlage unten). Auch die Täterrolle gibt einen ab.</li><li>Zettel einsammeln, der Reihe nach vorlesen. Noch nichts kommentieren.</li><li><b>Jetzt Teil B öffnen.</b></li></ol>\n<p><b>Anklagezettel (Vorlage, A6):</b></p>\n<pre class=\"plan\">DER LETZTE STERN VON EICHENFELS · ANKLAGE\nMein Name: ____________________\nIch klage an: ____________________\nWeil (Motiv): ____________________\nDer Beweis, der es zeigt: ____________________</pre>\n<h2>A7 · Wenn es stockt</h2>\n<p>Diese Impulse helfen weiter, ohne etwas zu verraten. Nimm höchstens einen pro Phase.</p>\n<ul><li><b>Phase 2:</b> „Wer hat Professor Sander nach der Ansprache als Letztes gesehen?“</li><li><b>Phase 3:</b> „Wer im Haus hat einen Namen mit R?“ · „Was ist eine Archivliste, und wer führt sie?“</li><li><b>Phase 4:</b> „Welche Türen konnte man während des Stromausfalls öffnen – und welche nicht?“ · „Wer konnte die Restaurierung überhaupt öffnen?“</li><li><b>Immer:</b> „Wer hat etwas verschwiegen? Das ist erlaubt. Aber warum?“</li></ul>\n<p><b>Wenn jemand Regel 2 bricht:</b> Freundlich daran erinnern. Ein Versehen wird korrigiert, nicht bestraft.</p>", "hostB": "", "guide": "<p><i>Für alle, die mitspielen. Diese Anleitung verrät nichts über die Lösung.</i></p>\n<hr>\n<h2>Worum es geht</h2>\n<p>Ein Novemberabend in der Sternwarte Eichenfels im Thüringer Wald. Professor Theodor Sander feiert das 125-jährige Jubiläum des Hauses und kündigt beim Dinner an, um 22 Uhr „die Wahrheit“ zu erzählen. Er erlebt diese Rede nicht mehr. Ein Unwetter hat die Zufahrt blockiert, die Polizei kommt erst im Morgengrauen. Bis dahin seid ihr unter euch – und eine Person am Tisch hat es getan.</p>\n<p>Jede und jeder von euch spielt eine Figur mit eigener Geschichte, eigenen Geheimnissen und eigenen Zielen. Gemeinsam findet ihr heraus, wer Professor Sander getötet hat. Eine Person weiß es schon: die Täterin oder der Täter. Nur weiß niemand, wer das ist.</p>\n<p><b>4 bis 10 Personen · etwa 2 bis 2½ Stunden · eine Spielleitung, die mitspielen darf</b></p>\n<hr>\n<h2>Vor dem Abend</h2>\n<ol><li>Die Spielleitung trägt alle Namen ein und wählt für jede Person die <b>Rollenvariante</b> – weiblich oder männlich dargestellt. Das ist eine Frage der Figur, nicht der Person: Jede und jeder darf wählen.</li><li>Die Rollen werden zufällig verteilt. Jede Person bekommt einen <b>eigenen Code</b> und öffnet damit ihr Rollenblatt (oder bekommt es ausgedruckt im verschlossenen Umschlag).</li><li><b>Lies dein Rollenblatt zwei, drei Tage vorher.</b> Es hat vier Seiten:<ul><li><b>Seite 1 · Dein Charakter und deine Vorgeschichte:</b> Wer du bist und woher du die anderen kennst.</li><li><b>Seite 2 · Deine Kleidung:</b> ein Vorschlag fürs Kostüm und dein <b>Requisit</b>.</li><li><b>Seite 3 · Was du weißt:</b> dein Abend, Minute für Minute, und was du über andere weißt.</li><li><b>Seite 4 · vertraulich:</b> dein Geheimnis, deine drei Ziele und Spielhinweise für jede Phase.</li></ul></li><li><b>Kostüm:</b> Niemand muss etwas kaufen. Was du im Schrank hast, reicht. <b>Steht bei deinem Requisit „Pflicht“, bring es bitte mit.</b> Es gehört zum Spiel.</li></ol>\n<hr>\n<h2>Die fünf Regeln</h2>\n<p><b>Regel 1 – Geheimnisse.</b> Du darfst dein Geheimnis verschweigen, Fragen ausweichen, Motive herunterspielen und Wissen für dich behalten. Niemand muss freiwillig alles erzählen.</p>\n<p><b>Regel 2 – Wahrheit und Lüge.</b> Wer <b>unschuldig</b> ist, sagt über den eigenen <b>Aufenthaltsort und die eigenen Handlungen zur Tatzeit</b> die Wahrheit. Nur die Täterrolle darf darüber lügen. Ob du die Täterrolle hast, steht auf deinem Rollenblatt – und nur dort.</p>\n<p><b>Regel 3 – Beweise sind wahr.</b> Was auf einer Beweiskarte steht, gilt.</p>\n<p><b>Regel 4 – Trumpfkarten.</b> Manche Rollen haben ein Wissen, das sie ausspielen können. Wann, entscheidest du – oder gar nicht.</p>\n<p><b>Regel 5 – Vertrauliches bleibt vertraulich.</b> Seite 4 deines Rollenblatts zeigst du niemandem vor dem Finale. Aus den Seiten 1–3 darfst du erzählen, so viel du willst.</p>\n<hr>\n<h2>Der Ablauf</h2>\n<table><thead><tr><th>Phase</th><th>Was passiert</th><th>Dauer</th></tr></thead><tbody><tr><td><b>1 · Der Empfang</b></td><td>Begrüßung, alle stellen ihre Figur vor. Professor Sander hält seine Ansprache.</td><td>ca. 20 Min.</td></tr><tr><td><b>2 · Der Mord</b></td><td>Der Fund. Die ersten Beweise. Jede Person sagt, wo sie zwischen 21:00 und 21:35 Uhr war.</td><td>ca. 20 Min.</td></tr><tr><td><b>3 · Geheimnisse und Intrigen</b></td><td>Neue Beweise. Befragt einander, schließt Bündnisse, verfolgt eure Ziele.</td><td>ca. 30 Min.</td></tr><tr><td><b>4 · Die letzte Ermittlung</b></td><td>Die letzten Beweise. Setzt die Teile zusammen.</td><td>ca. 25 Min.</td></tr><tr><td><b>Finale · Anklage und Auflösung</b></td><td>Jede Person gibt verdeckt ab, wen sie anklagt. Dann wird aufgelöst.</td><td>15–30 Min.</td></tr></tbody></table>\n<p>Die Spielleitung liest zu Beginn jeder Phase einen kurzen Text vor und gibt die Beweise frei – auf eure Handys oder als Karten auf den Tisch.</p>\n<hr>\n<h2>Die Anklage</h2>\n<p>Im Finale schreibt jede und jeder verdeckt auf:</p>\n<ol><li><b>Wer</b> hat Professor Sander getötet?</li><li><b>Warum?</b></li><li><b>Welcher Beweis</b> überführt die Person?</li></ol>\n<p>Danach legt die Täterrolle ihr Rollenblatt offen, die letzten Beweise werden geöffnet, und die Spielleitung liest vor, was wirklich geschah.</p>\n<p><b>Punkte (wenn ihr wollt):</b> Täter richtig 3 · Motiv richtig 1 · entscheidender Beweis 1 · jedes erreichte eigene Ziel 1. Die Täterrolle bekommt 4 Punkte, wenn höchstens eine Minderheit richtig anklagt.</p>\n<hr>\n<h2>Tipps für einen guten Abend</h2>\n<ul><li><b>Spiel deine Figur, nicht dich selbst.</b> Es ist erlaubt, eitel, misstrauisch oder gekränkt zu sein.</li><li><b>Frag nach Uhrzeiten.</b> Fast alles in diesem Fall hängt an Minuten.</li><li><b>Zeichne mit.</b> Ein Zettel mit einer Zeitleiste hilft mehr als jede Vermutung.</li><li><b>Nicht jede Person, die lügt, hat gemordet.</b> Fast alle haben etwas zu verbergen.</li><li><b>Die Täterrolle darf sich gut verteidigen.</b> Ein Fall ist erst dann schön gelöst, wenn er nicht zu leicht war.</li><li>Wer die Täterrolle hat: Du gewinnst nicht durch Schweigen, sondern durch eine Geschichte, die lange hält.</li></ul>"};
